   "Égoutte thon au naturel. Les quantités de conserves correspondent aux aliments égouttés. Le thon utilisé est au naturel.",
   "Lave les ingrédients frais, puis prépare courgette, tomate fraîche. Coupe les légumes en petits morceaux pour une cuisson régulière ; retire les noyaux, pépins durs et parties non comestibles.",
   "Préchauffe le petit four à 180 °C. Coupe les courgettes en deux, retire les graines ou creuse légèrement la chair. Précuis les coques 12 à 15 minutes dans un petit plat avec un fond d’eau.",
   "Fais revenir les légumes préparés à feu moyen : 3 à 5 minutes pour les épinards, 6 à 10 minutes pour les courgettes ou poivrons, davantage si nécessaire pour les légumes fermes. Le brocoli peut être précuit 5 à 7 minutes dans l’eau avant de rejoindre la poêle. Utilise l’huile déjà comptée, ou un fond d’eau pour finir la cuisson.",
   "Mélange la garniture cuite, les légumineuses ou le thon et le féculent s’ils sont présents. Ajoute les tomates et la sauce prévue, puis garnis les coques précuites.",
   "Ajoute le fromage s’il est indiqué et termine au four 12 à 20 minutes à 180 °C. Les légumes doivent être tendres et la farce bien chaude. Dans un petit four, prépare plusieurs fournées si le plat est trop grand.",
   "Termine avec les sauces, le fromage ou les garnitures encore prévus dans la liste, puis répartis selon les portions affichées. Les étapes s’appuient sur ces quantités : toute garniture ajoutée doit aussi être ajoutée aux ingrédients."
