   "Fais griller le pain si tu le souhaites. Garde-le pour accompagner la préparation, ou garnis-le au moment de servir avec les ingrédients prévus.",
   "Pour butternut, coupe en petits cubes et cuis à couvert avec un fond d’eau 12 à 18 minutes à la poêle, ou 6 à 10 minutes au micro-ondes dans un plat adapté. Vérifie la tendreté à la fourchette. Pour une patate douce garnie, garde la peau lavée, pique-la puis cuis-la entière au micro-ondes avant de l’ouvrir.",
   "Fais revenir les légumes préparés à feu moyen : 3 à 5 minutes pour les épinards, 6 à 10 minutes pour les courgettes ou poivrons, davantage si nécessaire pour les légumes fermes. Le brocoli peut être précuit 5 à 7 minutes dans l’eau avant de rejoindre la poêle. Utilise l’huile déjà comptée, ou un fond d’eau pour finir la cuisson.",
   "Pour les œufs de cette recette, cuis-les durs 9 à 10 minutes dans l’eau frémissante, refroidis-les sous l’eau froide puis écale et coupe-les. Si des blancs d’œufs seuls sont prévus, cuis-les à la poêle jusqu’à ce qu’ils soient pris.",
   "Cuis le butternut dans un fond d’eau à couvert jusqu’à ce qu’il soit tendre, puis mixe avec le lait d’avoine. Travaille en petites quantités dans le hachoir et laisse tiédir avant de mixer pour éviter les projections.",
   "Prépare les tartines avec les œufs cuits et le skyr. Sers-les à côté du velouté ; leurs quantités font partie de la portion affichée.",
