   "Répartis l’huile prévue pour l’ensemble de la cuisson : émiette le bœuf haché et cuis-le 6 à 8 minutes à la poêle, jusqu’à cuisson complète. Réserve les éléments cuits pendant la préparation du reste.",
   "Fais revenir les légumes préparés à feu moyen : 3 à 5 minutes pour les épinards, 6 à 10 minutes pour les courgettes ou poivrons, davantage si nécessaire pour les légumes fermes. Le brocoli peut être précuit 5 à 7 minutes dans l’eau avant de rejoindre la poêle. Utilise l’huile déjà comptée, ou un fond d’eau pour finir la cuisson.",
   "Réchauffe les champignons égouttés dans la poêle 2 à 3 minutes pour faire évaporer leur eau, puis incorpore-les à la préparation.",
   "Réunis le féculent, les protéines et la garniture dans la poêle ou dans le bol de service. Réchauffe le thon et les légumineuses quelques minutes s’ils sont présents, sans cuire longuement le thon en conserve.",
   "Termine avec les sauces, le fromage ou les garnitures encore prévus dans la liste, puis répartis selon les portions affichées. Les étapes s’appuient sur ces quantités : toute garniture ajoutée doit aussi être ajoutée aux ingrédients."
