   "Lave ou épluche les fruits indiqués. Retire noyaux et parties non comestibles, puis coupe banane en morceaux. Les quantités de fruits correspondent à la chair comestible.",
   "Verse les flocons et le lait indiqué dans une petite casserole. Ajoute un peu d’eau si les flocons ne sont pas correctement humidifiés.",
   "Chauffe à feu doux 5 à 7 minutes en remuant souvent, jusqu’à ce que les flocons soient tendres. Tu peux cuire les morceaux de pomme ou de poire avec le porridge.",
   "Retire du feu, attends une minute puis incorpore le skyr ou la whey. La poudre s’intègre mieux en la délayant d’abord dans une cuillère de liquide tiède.",
