   "Fais revenir les légumes préparés à feu moyen : 3 à 5 minutes pour les épinards, 6 à 10 minutes pour les courgettes ou poivrons, davantage si nécessaire pour les légumes fermes. Le brocoli peut être précuit 5 à 7 minutes dans l’eau avant de rejoindre la poêle. Utilise l’huile déjà comptée, ou un fond d’eau pour finir la cuisson.",
