   "Pour les œufs de cette recette, cuis-les durs 9 à 10 minutes dans l’eau frémissante, refroidis-les sous l’eau froide puis écale et coupe-les. Si des blancs d’œufs seuls sont prévus, cuis-les à la poêle jusqu’à ce qu’ils soient pris.",
   "Fais griller le pain si tu le souhaites, puis répartis les produits laitiers, les protéines et les crudités indiqués sur les tartines.",
   "Termine avec les sauces, le fromage ou les garnitures encore prévus dans la liste, puis répartis selon les portions affichées. Les étapes s’appuient sur ces quantités : toute garniture ajoutée doit aussi être ajoutée aux ingrédients."
